<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { api, date } from '../lib/api';
import { categoryNames, operationNames, ruleNames, type RiskControl } from '../lib/risk';
import Icon from './Icon.vue';
import Modal from './Modal.vue';
import Pagination from './Pagination.vue';
import RiskSettings from './RiskSettings.vue';
import RiskCustomerEditor from './RiskCustomerEditor.vue';

type Event = {id:number;category:string;severity:string;message:string;user_id:string;user_name:string;account:string;key_id:string;key_name:string;source_ip:string;source_verified:boolean;operation:string;rule:string;status:number;occurrences:number;last_seen:string;resolved_at:string|null};
type Restriction = {id:string;rule:string;label:string;user_id:string;key_id:string;count:number;blocked_until:string};
type Traffic = {user_id:string;user_name:string;email:string;key_id:string;key_name:string;operation:string;channel:string;requests:number;errors:number;blocked:number;average_ms:number};
type Customer = RiskControl & {email:string;name:string};
type Monitor = {items:Event[];total:number;summary:Record<string,number>;restrictions:Restriction[];customers:Customer[];traffic:Traffic[];generated_at:string;last_scan:string;refresh_seconds:number;monitoring_enabled:boolean};
const emit=defineEmits<{toast:[message:string]}>();
const data=ref<Monitor>(),settings=ref(false),error=ref(''),loading=ref(false),busy=ref(false),auto=ref(true);
const panel=ref('events'),q=ref(''),category=ref(''),state=ref(''),page=ref(1),size=ref(100);
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const start=ref(today),end=ref(today),customer=ref<{id?:string;label?:string}>();
const confirmation=ref<{path:string;title:string;description:string}>();
const stats=[['requests','业务访问'],['login_failures','登录失败'],['blocked','限流拦截'],['pending','待处理告警'],['restrictions','当前访问限制'],['paused_customers','暂停申请客户']];
const tabs=[['events','风险事件'],['limits','当前限制'],['traffic','访问统计']];
const summary=computed(()=>data.value?.summary||{});
let controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,searchTimer:ReturnType<typeof setTimeout>|undefined,disposed=false;
function schedule(){clearTimeout(timer);if(!disposed&&auto.value&&!settings.value&&!customer.value&&!confirmation.value&&!document.hidden)timer=setTimeout(()=>load(true),Math.max(5,data.value?.refresh_seconds||10)*1000)}
async function load(quiet=false){
 if(disposed||settings.value)return;
 controller?.abort();const request=new AbortController();controller=request;if(!quiet)loading.value=true;
 try{const result=await api<Monitor>('/api/admin/risk-monitor?'+new URLSearchParams({q:q.value,category:category.value,state:state.value,start:start.value,end:end.value,page:String(page.value),size:String(size.value)}),{signal:request.signal});if(controller===request){data.value=result;error.value=''}}catch(e){if((e as Error).name!=='AbortError'&&controller===request)error.value=(e as Error).message}finally{if(controller===request){loading.value=false;schedule()}}
}
function filter(){if(page.value!==1)page.value=1;else load()}
function edit(id?:string,label?:string){customer.value={id,label}}
function ask(path:string,title:string,description:string){confirmation.value={path,title,description}}
async function act(){const current=confirmation.value;if(!current)return;busy.value=true;error.value='';try{await api(current.path,{method:'POST',body:'{}'});confirmation.value=undefined;emit('toast','操作已完成');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function resolve(id:number){busy.value=true;try{await api(`/api/admin/risk-events/${id}/resolve`,{method:'POST',body:'{}'});emit('toast','事件已标记处理');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function active(c:Customer){return c.paused&&(!c.paused_until||Date.parse(c.paused_until)>Date.now())}
function visibility(){if(document.hidden){clearTimeout(timer)}else if(!settings.value&&!customer.value&&!confirmation.value)load(true)}
watch([category,state,start,end],filter);watch([page,size],()=>load());
watch(q,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(filter,300)});
watch([auto,customer,confirmation],schedule);
watch(settings,value=>{controller?.abort();loading.value=false;clearTimeout(timer);if(!value)load()});
onMounted(()=>{load();document.addEventListener('visibilitychange',visibility)});
onUnmounted(()=>{disposed=true;controller?.abort();clearTimeout(timer);clearTimeout(searchTimer);document.removeEventListener('visibilitychange',visibility)});
</script>

<template>
 <RiskSettings v-if="settings" @back="settings=false" @toast="emit('toast',$event)"/>
 <section v-else class="risk-monitor">
  <header class="risk-heading"><div><p class="eyebrow">RISK MONITOR</p><h2>风控监控</h2><p class="muted">关注异常访问、申请和积分，按客户独立处理。</p></div><div class="risk-actions"><label class="risk-auto"><input v-model="auto" type="checkbox"/>自动刷新</label><button class="button secondary" :disabled="loading" @click="load()"><Icon name="RefreshCw"/>刷新</button><button class="button primary" @click="settings=true"><Icon name="Settings"/>配置</button></div></header>
  <p v-if="error" class="error-banner" role="alert">{{error}}</p>
  <p v-if="data&&!data.monitoring_enabled" class="risk-notice">当前已关闭风控记录与异常检查，历史记录仍可查看。已配置的执行限制继续生效。</p>
  <div class="risk-metrics"><article v-for="[key,label] in stats" :key="key"><span>{{label}}</span><strong :class="{'risk-attention':key==='pending'&&summary[key!]}">{{(summary[key!]||0).toLocaleString()}}</strong><small>{{['restrictions','paused_customers'].includes(key!)?'当前全站状态':'所选日期与搜索范围'}}</small></article></div>
  <div class="risk-toolbar"><label>开始日期<input v-model="start" aria-label="风控开始日期" type="date"/></label><label>结束日期<input v-model="end" aria-label="风控结束日期" type="date"/></label><label class="risk-search">查找客户 / 密钥 / 来源<input v-model="q" aria-label="风控搜索" placeholder="邮箱、客户称呼、密钥名称或 IP" maxlength="254"/></label><div class="risk-update muted"><span>更新 {{data?date(data.generated_at):'—'}}</span><span>异常检查 {{data&&Date.parse(data.last_scan)>0?date(data.last_scan):'等待首次检查'}}</span></div></div>
  <nav class="risk-tabs" aria-label="风控视图"><button v-for="[key,label] in tabs" :key="key" :class="{selected:panel===key}" @click="panel=key!">{{label}}</button></nav>
  <section v-if="panel==='events'" class="table-card risk-card"><div class="risk-card-heading"><div><h3>风险事件</h3><p class="muted">同一分钟内相同事件合并计数；“已处理”表示已查看处理，不会自动解除限制。</p></div><div class="risk-actions"><select v-model="category" aria-label="事件分类"><option value="">全部分类</option><option v-for="(name,key) in categoryNames" :key="key" :value="key">{{name}}</option></select><select v-model="state" aria-label="事件处理状态"><option value="">全部状态</option><option value="pending">待处理告警</option><option value="resolved">已处理</option></select></div></div>
   <div class="table-scroll"><table><thead><tr><th>最近发生</th><th>事件 / 规则</th><th>客户 / 密钥</th><th>访问来源</th><th>次数 / 响应</th><th>处理</th></tr></thead><tbody><tr v-for="e in data?.items" :key="e.id"><td class="nowrap">{{date(e.last_seen)}}<small>{{categoryNames[e.category]}}</small></td><td><span class="risk-badge" :class="e.severity">{{e.severity==='critical'?'高关注':e.severity==='warning'?'关注':'记录'}}</span><span>{{e.message}}</span><small>{{operationNames[e.operation]}}{{e.rule?' · '+ruleNames[e.rule]:''}}</small></td><td><button v-if="e.user_id" class="risk-link" @click="edit(e.user_id,e.account)">{{e.user_name||e.account||'客户'}}</button><span v-else>{{e.account||'未登录访问'}}</span><small v-if="e.user_name">{{e.account}}</small><small v-if="e.key_id">{{e.key_name||'API 密钥'}}</small></td><td>{{e.source_ip||'—'}}<small v-if="e.source_ip">{{e.source_verified?'已核实来源':'来源未核实'}}</small></td><td>{{e.occurrences.toLocaleString()}} 次<small>{{e.status?'HTTP '+e.status:'后台检查'}}</small></td><td><span v-if="e.resolved_at" class="muted">已处理</span><span v-else-if="e.severity==='info'" class="muted">记录</span><button v-else class="button small secondary" :disabled="busy" @click="resolve(e.id)">标记已处理</button></td></tr><tr v-if="!data?.items.length"><td colspan="6" class="empty-state">{{loading?'正在读取事件…':'当前范围没有风险事件'}}</td></tr></tbody></table></div><Pagination v-model:page="page" v-model:size="size" :sizes="[100]" :total="data?.total||0" label="风控事件分页"/>
  </section>
  <template v-else-if="panel==='limits'">
   <section class="table-card risk-card"><div class="risk-card-heading"><div><h3>正在生效的访问限制</h3><p class="muted">全站当前限制，最多显示 100 项；解除后重新计数。不会因共用 IP 连带限制其他客户。</p></div></div><div class="table-scroll"><table><thead><tr><th>客户 / 密钥</th><th>限制规则</th><th>触发计数</th><th>自动解除时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in data?.restrictions" :key="r.id"><td>{{r.label}}</td><td>{{ruleNames[r.rule]}}</td><td>{{r.count}}</td><td>{{date(r.blocked_until)}}</td><td><button class="button small secondary" @click="ask(`/api/admin/risk-limits/${r.id}/release`,'解除访问限制',`解除 ${r.label} 的${ruleNames[r.rule]}限制，后续请求将重新计数。`)">解除限制</button></td></tr><tr v-if="!data?.restrictions.length"><td colspan="5" class="empty-state">当前没有生效的访问限制</td></tr></tbody></table></div></section>
   <section class="table-card risk-card"><div class="risk-card-heading"><div><h3>客户独立规则</h3><p class="muted">显示最近配置且生效的最多 100 位客户。暂停仅阻止新申请；查询、撤回和已受理任务继续。</p></div><button class="button secondary" @click="edit()">配置客户</button></div><div class="table-scroll"><table><thead><tr><th>客户</th><th>新申请</th><th>自动恢复</th><th>独立次数</th><th>操作</th></tr></thead><tbody><tr v-for="c in data?.customers" :key="c.user_id"><td>{{c.name}}<small>{{c.email}}</small></td><td><span class="risk-badge" :class="active(c)?'warning':'info'">{{active(c)?'已暂停':'正常'}}</span></td><td>{{active(c)?c.paused_until?date(c.paused_until):'手动恢复':'—'}}</td><td><small v-for="(count,key) in c.limits" :key="key">{{ruleNames[key]}}：{{count}}</small><span v-if="!Object.keys(c.limits).length">使用全局规则</span></td><td><button class="button small secondary" @click="edit(c.user_id,c.email)">调整 / 恢复</button></td></tr><tr v-if="!data?.customers.length"><td colspan="5" class="empty-state">客户均使用全局规则</td></tr></tbody></table></div></section>
  </template>
  <section v-else class="table-card risk-card"><div class="risk-card-heading"><div><h3>访问统计</h3><p class="muted">所选日期与客户/密钥搜索范围内，按访问量显示前 100 项。总错误 {{summary.errors||0}} 次，平均 {{summary.average_ms||0}} ms。风控页自身查询不计入。</p></div></div><div class="table-scroll"><table><thead><tr><th>客户</th><th>渠道 / 密钥</th><th>业务类型</th><th>访问 / 错误 / 拦截</th><th>平均响应</th><th>操作</th></tr></thead><tbody><tr v-for="(t,i) in data?.traffic" :key="i"><td>{{t.user_name||t.email||'未登录访问'}}<small v-if="t.user_name">{{t.email}}</small></td><td>{{t.channel==='api'?'API':'网页'}}<small>{{t.key_name}}</small></td><td>{{operationNames[t.operation]}}</td><td>{{t.requests}} / {{t.errors}} / {{t.blocked}}</td><td>{{t.average_ms}} ms</td><td><div class="risk-actions"><button v-if="t.user_id" class="button small secondary" @click="edit(t.user_id,t.email)">客户规则</button><button v-if="t.key_id" class="button small secondary" @click="ask(`/api/admin/risk-keys/${t.key_id}/revoke`,'撤销 API 密钥',`撤销 ${t.key_name||'此密钥'} 后，使用它的客户端将无法继续访问。已受理申请继续执行；此操作不可撤回。`)">撤销密钥</button></div></td></tr><tr v-if="!data?.traffic.length"><td colspan="6" class="empty-state">当前范围没有访问记录</td></tr></tbody></table></div></section>
  <RiskCustomerEditor v-if="customer" :user-id="customer.id" :label="customer.label" @close="customer=undefined" @saved="customer=undefined;load();emit('toast','客户风控规则已保存')"/>
  <Modal v-if="confirmation" :title="confirmation.title" :description="confirmation.description" :busy="busy" @close="!busy&&(confirmation=undefined)"><div class="risk-confirm"><p v-if="error" class="error-banner">{{error}}</p><button class="button secondary" :disabled="busy" @click="confirmation=undefined">取消</button><button class="button primary" :disabled="busy" @click="act">{{busy?'处理中…':'确认操作'}}</button></div></Modal>
 </section>
</template>

<style scoped>
.risk-monitor{min-width:0}.risk-heading,.risk-card-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.risk-heading h2{font-size:24px;margin:8px 0}.muted{font-size:12px;line-height:1.7}.risk-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.risk-auto{display:flex;align-items:center;gap:7px;font-size:12px;white-space:nowrap}.risk-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:20px 0}.risk-metrics article{background:var(--surface,#fff);border:1px solid var(--line,#e4e7eb);border-radius:12px;padding:18px}.risk-metrics span{display:block;font-size:12px;color:var(--muted,#718096)}.risk-metrics strong{display:block;font-size:28px;margin:10px 0}.risk-metrics small{font-size:10px;color:var(--muted,#718096)}.risk-attention{color:#c56822}.risk-toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:20px 0}.risk-toolbar label{display:grid;gap:7px;font-size:12px}.risk-search{flex:1;min-width:240px}.risk-update{display:grid;margin-left:auto}.risk-tabs{display:flex;gap:6px;margin:20px 0}.risk-tabs button{border:1px solid var(--line,#e4e7eb);padding:10px 20px;border-radius:9px;background:transparent;cursor:pointer}.risk-tabs button.selected{background:#174d4d;color:white;border-color:#174d4d}.risk-card{margin:0 0 20px;min-width:0}.risk-card-heading{padding:20px 20px 0}.risk-card h3{font-size:16px;margin:0 0 6px}.risk-card p{margin:0}.risk-card table{min-width:900px}.risk-card td{vertical-align:top;max-width:340px;overflow-wrap:anywhere}.risk-card td small{display:block;font-size:11px;color:var(--muted,#718096);margin-top:5px}.risk-card .nowrap{white-space:nowrap}.risk-link{color:#197370;cursor:pointer;background:none;border:0;padding:0;text-align:left}.risk-badge{display:inline-block;font-size:11px;padding:3px 7px;border-radius:5px;margin-right:7px;margin-bottom:5px;white-space:nowrap}.risk-badge.warning{background:#fff1d7;color:#915400}.risk-badge.critical{background:#ffe4e4;color:#b63d3d}.risk-badge.info{background:#e8f2ef;color:#266456}.risk-notice{background:#fff4dc;padding:12px 16px;border-radius:8px;font-size:13px}.risk-confirm{padding:22px;display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap}.risk-confirm .error-banner{width:100%}@media(max-width:1200px){.risk-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){.risk-heading,.risk-card-heading{flex-direction:column;align-items:stretch}.risk-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.risk-update{margin-left:0;width:100%}.risk-toolbar label{flex:1;min-width:130px}.risk-toolbar .risk-search{min-width:100%}.risk-heading .risk-actions{justify-content:space-between}.risk-tabs button{flex:1;padding:10px}.risk-card-heading{padding:15px 15px 0}}
</style>
